import{_ as n,C as i,c as l,o as h,a3 as r,G as s,j as t,a as o}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Leaving the company","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/employees/employees/leaving-the-company.md","filePath":"master/human-resources/employees/employees/leaving-the-company.md","lastUpdated":1791902625000}'),d={name:"master/human-resources/employees/employees/leaving-the-company.md"};function p(c,e,m,g,u,y){const a=i("ImagePopup");return h(),l("div",null,[e[0]||(e[0]=r('<h1 id="leaving-the-company" tabindex="-1">Leaving the company <a class="header-anchor" href="#leaving-the-company" aria-label="Permalink to &quot;Leaving the company&quot;">​</a></h1><p>When someone leaves, you record why and when, and you take them out of the active list. You do not need to erase the record. Keeping it preserves history such as skills, resumé and notes.</p><blockquote><p><strong>In simple words:</strong> Note the reason and date, switch the employee off, and keep the file.</p></blockquote><h2 id="record-the-departure" tabindex="-1">Record the departure <a class="header-anchor" href="#record-the-departure" aria-label="Permalink to &quot;Record the departure&quot;">​</a></h2><ol><li>Open the employee and click <strong>Edit</strong>.</li><li>Open the <strong>Settings</strong> tab.</li><li>Choose a <strong>Departure Reason</strong>: <strong>Fired</strong>, <strong>Resigned</strong> or <strong>Retired</strong>.</li><li>Two fields appear. Fill both. They are required. <ul><li><strong><em>Departure Date:</em></strong> the last working day.</li><li><strong><em>Departure Description:</em></strong> a short note about the departure.</li></ul></li><li>Turn <strong>Active Employee</strong> off.</li><li>Click <strong>Save changes</strong>.</li></ol><p>Example: Priya resigns. Choose <strong>Resigned</strong>, pick the last working day as <strong>Departure Date</strong>, and write the note.</p>',6)),s(a,{src:"/images1/employees/emp_leave_settings.png",alt:"Settings tab with Departure Reason Resigned, Departure Date and Departure Description"}),e[1]||(e[1]=r('<p>The reasons come from <a href="./../setup/departure-reasons.html">Departure reasons</a>. The plus button next to the field adds a new one.</p><p>If you clear <strong>Departure Reason</strong>, the date and description fields hide again.</p><h2 id="what-active-employee-means" tabindex="-1">What Active Employee means <a class="header-anchor" href="#what-active-employee-means" aria-label="Permalink to &quot;What Active Employee means&quot;">​</a></h2><p><strong>Active Employee</strong> is on for current staff. Turn it off for someone who has left. The profile shows it as <strong>Yes</strong> or <strong>No</strong> under <strong>Employee Settings</strong>.</p><h2 id="archive-instead-of-deleting" tabindex="-1">Archive instead of deleting <a class="header-anchor" href="#archive-instead-of-deleting" aria-label="Permalink to &quot;Archive instead of deleting&quot;">​</a></h2><p>Click <strong>Delete</strong> on the profile. A window asks <strong>Are you sure you would like to do this?</strong> Click the red <strong>Delete</strong> button to confirm. The employee moves to the <strong>Archived</strong> tab of the <a href="./employee-list.html">Employee list</a>. The record is kept, not erased.</p>',6)),s(a,{src:"/images1/employees/emp_leave_confirm.png",alt:"Delete Test Leaver window asking Are you sure you would like to do this, with Cancel and a red Delete button"}),e[2]||(e[2]=t("p",null,[o("On the "),t("strong",null,"Archived"),o(" tab, each card shows the name, job title, "),t("strong",null,"View"),o(", "),t("strong",null,"Edit"),o(" and "),t("strong",null,"Restore"),o(". There is no "),t("strong",null,"Delete"),o(" on an archived card.")],-1)),s(a,{src:"/images1/employees/emp_leave_archived.png",alt:"Archived tab showing the Test Leaver card with the View, Edit and Restore actions"}),e[3]||(e[3]=r('<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Archive an employee instead of keeping them on the <strong>Default</strong> tab. The record stays safe and you can restore it.</p></div><h2 id="restore" tabindex="-1">Restore <a class="header-anchor" href="#restore" aria-label="Permalink to &quot;Restore&quot;">​</a></h2><p>Open the <strong>Archived</strong> tab and click <strong>Restore</strong> on the employee&#39;s card.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>The departure details are saved on the employee record. Filters in the employee list can use <strong>Departure Date</strong> and <strong>Departure Reason</strong>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./employee-profile.html">Employee profile</a></li><li><a href="./employee-list.html">Employee list</a></li><li><a href="./../setup/departure-reasons.html">Departure reasons</a></li></ul>',7))])}const v=n(d,[["render",p]]);export{_ as __pageData,v as default};
